<?php $resourcePath=$resourcePath??'/admin/posts'; ?><div class="table-wrap"><table><thead><tr><th>Contenido</th><th>Categoría</th><th>Estado</th><th>Fecha</th><th></th></tr></thead><tbody><?php foreach($posts as $post):?><tr><td><div class="table-story"><img src="<?= e(post_image($post['image'])) ?>" alt=""><b><?= e($post['title']) ?></b></div></td><td><?= e($post['category_name']) ?></td><td><span class="status <?= e($post['status']) ?>"><?= $post['status']==='published'?'Publicada':'Borrador' ?></span></td><td><?= e(date_es($post['published_at'])) ?></td><td class="actions"><a href="<?= url($resourcePath.'/'.$post['id'].'/edit') ?>">Editar</a><form method="post" action="<?= url($resourcePath.'/'.$post['id']) ?>" onsubmit="return confirm('¿Eliminar este contenido?')"><?= csrf_field() ?><input type="hidden" name="_method" value="DELETE"><button>Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div>
